## Waiting for the action to finish

By default the action closes the dialog at once. When the work can fail, or takes a moment, keep the dialog open until it's done: control `open`, and call `event.preventDefault()` in the action's `onClick`.

```tsx
"use client";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogTrigger,
  Button,
} from "@nuvui/react";
import { type MouseEvent, useRef, useState } from "react";

// Stands in for a request to your server. So that both endings can be
// seen, the first one fails and the next goes through.
let tried = 0;
async function revokeAccess() {
  await new Promise((resolve) => setTimeout(resolve, 600));
  tried += 1;
  if (tried === 1) throw new Error("The server didn't answer.");
}

export default function Example() {
  const [open, setOpen] = useState(false);
  const [revoking, setRevoking] = useState(false);
  const [revoked, setRevoked] = useState(false);
  const [problem, setProblem] = useState("");
  const status = useRef<HTMLParagraphElement>(null);

  async function revoke(event: MouseEvent) {
    // Keeps the dialog open. It closes below, once the request is through.
    event.preventDefault();
    setRevoking(true);
    setProblem("");
    try {
      await revokeAccess();
      setRevoked(true);
      setOpen(false);
    } catch {
      // It didn't go through, so the dialog stays, says so, and can be
      // tried again or left.
      setProblem("Access couldn't be revoked. Try again.");
    } finally {
      setRevoking(false);
    }
  }

  return (
    <div style={{ display: "grid", gap: 12, justifyItems: "center" }}>
      <AlertDialog
        open={open}
        onOpenChange={(next) => {
          setOpen(next);
          if (!next) setProblem("");
        }}
      >
        <AlertDialogTrigger asChild>
          <Button intent="secondary" disabled={revoked}>
            Revoke access
          </Button>
        </AlertDialogTrigger>
        <AlertDialogContent
          size="sm"
          onCloseAutoFocus={(event) => {
            // Once it's done, the button that opened this is disabled and
            // can't take the focus back. The line that says what happened
            // takes it.
            if (!revoked) return;
            event.preventDefault();
            status.current?.focus();
          }}
        >
          <AlertDialogTitle>Revoke Sam's access?</AlertDialogTitle>
          <AlertDialogDescription>
            Sam will be signed out and won't be able to open the workspace.
          </AlertDialogDescription>
          {problem && (
            <p role="alert" style={{ margin: 0, color: "var(--color-danger)" }}>
              {problem}
            </p>
          )}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={revoking}>
              Keep access
            </AlertDialogCancel>
            <AlertDialogAction
              intent="danger"
              disabled={revoking}
              onClick={revoke}
            >
              {revoking ? "Revoking" : "Revoke access"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      <p ref={status} tabIndex={-1} style={{ margin: 0, fontSize: 14 }}>
        {revoked ? "Sam no longer has access." : "Sam has access."}
      </p>
    </div>
  );
}
```

Disable both buttons while the request is running, so it can't be sent twice or abandoned halfway.

When the work fails, leave the dialog open and say so inside it, in an element with `role="alert"` so it's read out. The buttons come back, to try again or to leave. The example's first try fails, so that this can be seen.

When it's done, the button that opened the dialog is often gone or disabled, as here, and the focus has nowhere to go back to. Say where it goes in `onCloseAutoFocus`: the line that says what happened, or whatever comes after what was removed.

## Opening one from a menu

A destructive item in a [dropdown menu](page:components/dropdown-menu) should ask before it acts. Put the alert dialog next to the menu, not inside the item, and open it from the item's `onSelect`.

```tsx
"use client";

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogTitle,
  Button,
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@nuvui/react";
import { useRef, useState } from "react";

export default function Example() {
  const [confirming, setConfirming] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const menuButton = useRef<HTMLButtonElement>(null);

  return (
    <div style={{ display: "grid", gap: 12, justifyItems: "center" }}>
      <DropdownMenu>
        <DropdownMenuTrigger asChild>
          <Button ref={menuButton} intent="secondary" disabled={deleted}>
            File
          </Button>
        </DropdownMenuTrigger>
        <DropdownMenuContent>
          <DropdownMenuItem>Rename</DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem
            intent="danger"
            onSelect={() => setConfirming(true)}
          >
            Delete
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>

      {/* Next to the menu, not inside the item. The menu takes its items off
          the page when it closes, and the dialog would go with them. */}
      <AlertDialog open={confirming} onOpenChange={setConfirming}>
        <AlertDialogContent
          size="sm"
          // The dialog would put focus back where it was when it opened,
          // which is the menu item, and that's gone. Send it to the button.
          onCloseAutoFocus={(event) => {
            event.preventDefault();
            menuButton.current?.focus();
          }}
        >
          <AlertDialogTitle>Delete report.pdf?</AlertDialogTitle>
          <AlertDialogDescription>
            It goes to the trash, and is removed for good after 30 days.
          </AlertDialogDescription>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction intent="danger" onClick={() => setDeleted(true)}>
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <p style={{ margin: 0, fontSize: 14 }}>
        {deleted ? "report.pdf is in the trash." : "report.pdf"}
      </p>
    </div>
  );
}
```

There's no trigger here for focus to go back to when the dialog closes. Left alone, Radix returns it to whatever had it when the dialog opened, which is the menu item, and that's no longer on the page. So the example says where it should go, in `onCloseAutoFocus`: the button that opened the menu.

## Roll or pop

With `animation="roll"`, the default, each digit that changes turns through the digits between the old one and the new one, the way the number went: up through nine to zero when it rose, down when it fell. With `animation="pop"`, the old digit rises out of sight as the new one rises into place, coming into focus.

```tsx
"use client";

import { AnimatedNumber, Button } from "@nuvui/react";
import { useState } from "react";

const prices = [19, 24, 49];

export default function Example() {
  const [plan, setPlan] = useState(1);

  return (
    <div style={{ display: "grid", gap: 16, justifyItems: "center" }}>
      <span style={{ fontSize: "var(--text-4xl)", fontWeight: 600 }}>
        <AnimatedNumber
          value={prices[plan] ?? 0}
          animation="pop"
          currency="GBP"
          locale="en-GB"
          maximumFractionDigits={0}
        />
      </span>
      <Button
        intent="secondary"
        onClick={() => setPlan((now) => (now + 1) % prices.length)}
      >
        Next plan
      </Button>
    </div>
  );
}
```

Either way only the digits that changed move, from the left, each a moment after the one before. Separators, signs, currency symbols and the letters of a short form such as 1.2K stay where they are.

## Languages and currencies

It writes the number as [FormattedNumber](page:components/formatted-number) does, with the same props: a language, a currency, a percentage, a short form. Any currency is given by its ISO 4217 code, such as `"EUR"`, `"GBP"` or `"JPY"`, and `locale` says how it's written: the sign before the number or after it, a comma or a point, and how many decimals the currency has. The sign stays where it is, and only the digits move.

```tsx
"use client";

import { AnimatedNumber, Button } from "@nuvui/react";
import { useState } from "react";

// One plan's price in four markets, each written the way its own
// customers write money: the sign before the number or after it, a comma
// or a point, and yen with no cents.
const markets = [
  { name: "Germany", currency: "EUR", locale: "de-DE", price: 49 },
  { name: "United Kingdom", currency: "GBP", locale: "en-GB", price: 42 },
  { name: "Japan", currency: "JPY", locale: "ja-JP", price: 7800 },
  { name: "India", currency: "INR", locale: "en-IN", price: 3999 },
];

export default function Example() {
  const [yearly, setYearly] = useState(false);

  return (
    <div style={{ display: "grid", gap: 16, justifyItems: "start" }}>
      <dl
        style={{
          display: "grid",
          gridTemplateColumns: "auto auto",
          gap: "0.5rem 2rem",
          margin: 0,
        }}
      >
        {markets.map((market) => (
          <div key={market.name} style={{ display: "contents" }}>
            <dt>{market.name}</dt>
            <dd style={{ margin: 0, textAlign: "end", fontWeight: 600 }}>
              <AnimatedNumber
                value={yearly ? market.price * 10 : market.price}
                currency={market.currency}
                locale={market.locale}
              />
            </dd>
          </div>
        ))}
      </dl>
      <Button
        intent="secondary"
        aria-pressed={yearly}
        onClick={() => setYearly((now) => !now)}
      >
        Show yearly prices
      </Button>
    </div>
  );
}
```

The two have to agree with your customer, not with each other: a price in euros for someone in Ireland is `locale="en-IE"`, and for someone in Germany `locale="de-DE"`. In a language whose numbers have digits of their own, such as Arabic or Hindi, those are the digits that roll. In a language read from the right, the number is laid out the way the browser lays it out, and what moves is drawn over it.

## Saying that it changed

A screen reader doesn't read out a number because it changed. That's on purpose: a dashboard where every refresh was read out would be hard to use. For a number whose change someone needs to hear, such as the items in a cart, put it in an element with `aria-live="polite"`. It's read once, when the number has changed, and the moving digits aren't read at all.

```tsx
"use client";

import { AnimatedNumber, Button } from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [items, setItems] = useState(2);

  return (
    <div style={{ display: "flex", gap: 12, alignItems: "center" }}>
      <Button onClick={() => setItems((now) => now + 1)}>Add to cart</Button>
      {/* Read out once, when the number has changed. */}
      <span aria-live="polite">
        <AnimatedNumber value={items} /> items in your cart
      </span>
    </div>
  );
}
```

