```tsx
"use client";

import {
  Badge,
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxTrigger,
  ComboboxValue,
} from "@nuvui/react";
import { useState } from "react";

const labels = [
  "Billing",
  "Bug",
  "Documentation",
  "Feature request",
  "Performance",
  "Security",
];

export default function Example() {
  const [picked, setPicked] = useState(["Bug", "Security"]);

  return (
    <div style={{ display: "grid", gap: 8, maxWidth: 280 }}>
      <label htmlFor="labels">Labels</label>
      <Combobox multiple value={picked} onValueChange={setPicked}>
        <ComboboxTrigger id="labels">
          <ComboboxValue placeholder="Add labels">
            {picked.length === 1 ? picked[0] : `${picked.length} labels`}
          </ComboboxValue>
        </ComboboxTrigger>
        <ComboboxContent
          aria-label="Labels"
          label="Search labels"
          searchPlaceholder="Search"
        >
          <ComboboxEmpty>No label found.</ComboboxEmpty>
          {labels.map((label) => (
            <ComboboxItem key={label} value={label}>
              {label}
            </ComboboxItem>
          ))}
        </ComboboxContent>
      </Combobox>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
        {picked.map((label) => (
          <Badge key={label}>{label}</Badge>
        ))}
      </div>
    </div>
  );
}
```

The trigger is a button, so it can't hold a remove button for each value. Show what's picked next to it, as the badges are here, if people need to see all of it at once.

## How the search matches

An option stays while its text contains what was typed. Upper and lower case are the same, and so are letters with and without accents: `jose` finds José. The options keep the order you wrote them in.

The text that's searched is the option's children when they're a string. When they aren't, give `textValue`. `keywords` adds other words that should find the option. The `value` itself isn't searched, so an id doesn't turn up by accident.

```tsx
"use client";

import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxTrigger,
  ComboboxValue,
} from "@nuvui/react";
import { useState } from "react";

const people = [
  { id: "u_1", name: "Ada Okafor", email: "ada@example.com", team: "design" },
  { id: "u_2", name: "José Álvarez", email: "jose@example.com", team: "api" },
  { id: "u_3", name: "Mei Tanaka", email: "mei@example.com", team: "design" },
  { id: "u_4", name: "Priya Nair", email: "priya@example.com", team: "web" },
];

export default function Example() {
  const [id, setId] = useState("u_2");
  const person = people.find((item) => item.id === id);

  return (
    <Combobox value={id} onValueChange={setId}>
      <ComboboxTrigger aria-label="Owner">
        <ComboboxValue placeholder="Pick an owner">
          {person?.name}
        </ComboboxValue>
      </ComboboxTrigger>
      <ComboboxContent label="Search people" searchPlaceholder="Name or team">
        <ComboboxEmpty>Nobody found.</ComboboxEmpty>
        {people.map((item) => (
          <ComboboxItem
            key={item.id}
            value={item.id}
            textValue={item.name}
            keywords={[item.email, item.team]}
          >
            <span style={{ display: "grid" }}>
              <span>{item.name}</span>
              <span style={{ fontSize: 12 }}>{item.email}</span>
            </span>
          </ComboboxItem>
        ))}
      </ComboboxContent>
    </Combobox>
  );
}
```

Pass `filter` to match some other way. It's called with the value, the search and the keywords, where the first keyword is the option's text, and returns a number: zero hides the option, and options with a higher number come first.

```tsx
<ComboboxContent
  // Only options that start with what was typed.
  filter={(value, search, keywords) =>
    keywords?.[0]?.toLowerCase().startsWith(search.toLowerCase()) ? 1 : 0
  }
>
```

`comboboxFilter` is the filter used by default, exported so that yours can fall back on it.

## Options from a server

For a list too long to send in one go, fetch the matches as the person types. Control the search text with `search` and `onSearchChange`, and turn `shouldFilter` off, because what comes back is already the matches.

```tsx
"use client";

import {
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxLoading,
  ComboboxTrigger,
  ComboboxValue,
} from "@nuvui/react";
import { useEffect, useState } from "react";

const customers = [
  "Acme Corporation",
  "Blue Harbor Logistics",
  "Cedar & Stone",
  "Delta Freight",
  "Evergreen Health",
  "Fjord Analytics",
  "Globex",
  "Harbor Light Media",
];

// Stands in for a request to your server.
function searchCustomers(text: string): Promise<string[]> {
  const matches = customers.filter((name) =>
    name.toLowerCase().includes(text.toLowerCase()),
  );
  return new Promise((resolve) => setTimeout(() => resolve(matches), 600));
}

export default function Example() {
  const [search, setSearch] = useState("");
  const [results, setResults] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let current = true;
    setLoading(true);
    searchCustomers(search).then((matches) => {
      // An answer to an older search can arrive after a newer one.
      if (!current) return;
      setResults(matches);
      setLoading(false);
    });
    return () => {
      current = false;
    };
  }, [search]);

  return (
    <Combobox>
      <ComboboxTrigger aria-label="Customer">
        <ComboboxValue placeholder="Pick a customer" />
      </ComboboxTrigger>
      <ComboboxContent
        label="Search customers"
        searchPlaceholder="Search"
        search={search}
        onSearchChange={setSearch}
        // The server has already done the filtering.
        shouldFilter={false}
      >
        {loading ? <ComboboxLoading label="Loading customers" /> : null}
        <ComboboxEmpty>No customer found.</ComboboxEmpty>
        {loading
          ? null
          : results.map((name) => (
              <ComboboxItem key={name} value={name}>
                {name}
              </ComboboxItem>
            ))}
      </ComboboxContent>
    </Combobox>
  );
}
```

Render `ComboboxLoading` while a request is out. `ComboboxEmpty` waits while it's there: nothing has been found yet, which isn't the same as nothing matching.

The component keeps every option on the page, so a list of thousands is slow to open. Fetching as you type is the way to handle a list that long.

## In a form

Give `Combobox` a `name` and it renders a hidden input that carries the value. With `multiple` there's one input for each value, all under the same name. A single combobox with nothing picked sends an empty value, as a select does.

Inside a [field](page:components/field), wrap the trigger in `FieldControl`. The label, the description and the error are then tied to it.

```tsx
"use client";

import {
  Button,
  Combobox,
  ComboboxContent,
  ComboboxEmpty,
  ComboboxItem,
  ComboboxTrigger,
  ComboboxValue,
  Field,
  FieldControl,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@nuvui/react";
import { useState } from "react";

const plans = ["Starter", "Team", "Business", "Enterprise"];

export default function Example() {
  const [plan, setPlan] = useState("");
  const [submitted, setSubmitted] = useState(false);
  const error = submitted && !plan ? "Pick a plan to continue." : undefined;

  return (
    <form
      style={{ display: "grid", gap: 16, width: "100%", maxWidth: 280 }}
      onSubmit={(event) => {
        event.preventDefault();
        setSubmitted(true);
      }}
    >
      <Field required>
        <FieldLabel>Plan</FieldLabel>
        <Combobox value={plan} onValueChange={setPlan} name="plan">
          <FieldControl>
            <ComboboxTrigger style={{ inlineSize: "100%" }}>
              <ComboboxValue placeholder="Pick a plan" />
            </ComboboxTrigger>
          </FieldControl>
          <ComboboxContent
            aria-label="Plan"
            label="Search plans"
            searchPlaceholder="Search"
          >
            <ComboboxEmpty>No plan found.</ComboboxEmpty>
            {plans.map((name) => (
              <ComboboxItem key={name} value={name}>
                {name}
              </ComboboxItem>
            ))}
          </ComboboxContent>
        </Combobox>
        <FieldDescription>You can change it later.</FieldDescription>
        <FieldError>{error}</FieldError>
      </Field>
      <Button type="submit">Continue</Button>
    </form>
  );
}
```

The hidden input can't be `required` in the way the browser checks, so a required combobox is checked by your own code or your form library, as this example does.

## In a dialog

`CommandDialog` has no trigger part. It opens with its `shortcut`, or from anything that sets `open`.

```tsx
"use client";

import {
  Button,
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
  Kbd,
} from "@nuvui/react";
import { useState } from "react";

const pages = ["Dashboard", "Orders", "Customers", "Invoices", "Settings"];
const actions = ["Create an order", "Invite a teammate", "Export as CSV"];

export default function Example() {
  const [open, setOpen] = useState(false);
  const [last, setLast] = useState("");

  // Running a command closes the palette. That's yours to do.
  const run = (command: string) => {
    setLast(command);
    setOpen(false);
  };

  return (
    <div style={{ display: "grid", gap: 12, justifyItems: "center" }}>
      <Button intent="secondary" onClick={() => setOpen(true)}>
        Open the palette
      </Button>
      <p style={{ margin: 0, fontSize: 14 }}>
        Or press <Kbd>Ctrl</Kbd> <Kbd>J</Kbd>
      </p>
      <output style={{ fontSize: 14 }}>{last ? `Ran: ${last}` : null}</output>
      <CommandDialog
        open={open}
        onOpenChange={setOpen}
        // This site's own search has Ctrl+K.
        shortcut="j"
        label="Search commands"
      >
        <CommandInput placeholder="Where to, or what to do" />
        <CommandList>
          <CommandEmpty>Nothing found.</CommandEmpty>
          <CommandGroup heading="Go to">
            {pages.map((page) => (
              <CommandItem key={page} onSelect={run}>
                {page}
              </CommandItem>
            ))}
          </CommandGroup>
          <CommandGroup heading="Actions">
            {actions.map((action) => (
              <CommandItem key={action} onSelect={run}>
                {action}
              </CommandItem>
            ))}
          </CommandGroup>
        </CommandList>
      </CommandDialog>
    </div>
  );
}
```

`shortcut` takes a letter, and listens for it with <kbd>Ctrl</kbd>, or with <kbd>⌘</kbd> on a Mac. The same keys close the dialog again. Left out, there's no shortcut.

- Something that already uses the keys keeps them. An editor that handles <kbd>Ctrl</kbd> + <kbd>K</kbd> itself, and calls `preventDefault`, isn't interrupted.
- Text that's edited in place, in an element with `contenteditable`, keeps them too. The browser has uses of its own for some of them there.
- Otherwise the browser is stopped from acting on the keys. Firefox would move focus to its search bar on <kbd>Ctrl</kbd> + <kbd>K</kbd>.

Running a command doesn't close the dialog by itself. Some commands should leave it open, to pick a second thing say. Close it in `onSelect` when that's what you want, as the example does.

The search starts empty each time the dialog opens.

## Items from a server

Control the search text on `CommandInput`, fetch for it, and turn `shouldFilter` off on `Command`, because what comes back is already the matches.

```tsx
"use client";

import {
  Command,
  CommandEmpty,
  CommandInput,
  CommandItem,
  CommandList,
  CommandLoading,
} from "@nuvui/react";
import { useEffect, useState } from "react";

const orders = [
  "10248 · Acme Corporation",
  "10249 · Blue Harbor Logistics",
  "10250 · Cedar & Stone",
  "10251 · Delta Freight",
  "10252 · Evergreen Health",
];

// Stands in for a request to your server.
function searchOrders(text: string): Promise<string[]> {
  const matches = orders.filter((order) =>
    order.toLowerCase().includes(text.toLowerCase()),
  );
  return new Promise((resolve) => setTimeout(() => resolve(matches), 600));
}

export default function Example() {
  const [search, setSearch] = useState("");
  const [results, setResults] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let current = true;
    setLoading(true);
    searchOrders(search).then((matches) => {
      // An answer to an older search can arrive after a newer one.
      if (!current) return;
      setResults(matches);
      setLoading(false);
    });
    return () => {
      current = false;
    };
  }, [search]);

  return (
    <Command
      label="Search orders"
      // The server has already done the filtering.
      shouldFilter={false}
      style={{
        inlineSize: "100%",
        maxInlineSize: 420,
        border: "1px solid var(--color-border)",
      }}
    >
      <CommandInput
        placeholder="Order number or customer"
        value={search}
        onValueChange={setSearch}
      />
      <CommandList>
        {loading ? <CommandLoading label="Loading orders" /> : null}
        <CommandEmpty>No order found.</CommandEmpty>
        {loading
          ? null
          : results.map((order) => (
              <CommandItem key={order}>{order}</CommandItem>
            ))}
      </CommandList>
    </Command>
  );
}
```

Render `CommandLoading` while a request is out. `CommandEmpty` waits while it's there: nothing has been found yet, which isn't the same as nothing matching.

## The pictures

`before` and `after` take anything: an `img`, a `picture`, a `video`, or markup of your own. An `img` or a `video` fills the box and is cropped to it, as with `object-fit: cover`. Give each its own `alt`, which says what it shows, since the two are read one after the other.

The box is as tall as `after` is. For a shape of your own, set `--nuv-compare-ratio`, and both pictures are cropped to it:

```css
.kitchen {
  --nuv-compare-ratio: 16 / 9;
}
```

Use two pictures of the same size, taken from the same place. The divider only reads as a change if what doesn't change lines up.

## The divider

The divider moves only when it's dragged: by its handle, or by the line anywhere along its length. A drag anywhere else on the picture is the page's, so on a phone a finger on the picture scrolls the page as it does everywhere else. The line is as wide as a finger to take hold of, though it's drawn thinner. A picture in the box can't be picked up and dragged out of it, as a browser lets an image be, since a press on it was most likely meant for the divider.

`position` is how much of before shows, from 0 to 100. Leave it out and the divider starts at `defaultPosition`, which is 50. Set it, with `onPositionChange`, to move the divider from your own controls:

```tsx
"use client";

import { Button, ButtonGroup, Compare } from "@nuvui/react";
import { useState } from "react";
import { kitchenAfter, kitchenBefore } from "./pictures";

export default function Example() {
  const [position, setPosition] = useState(50);

  return (
    <div style={{ display: "grid", gap: 12, width: "100%", maxWidth: 560 }}>
      <Compare
        position={position}
        onPositionChange={setPosition}
        before={
          <img src={kitchenBefore} alt="The kitchen with its old cabinets" />
        }
        after={
          <img src={kitchenAfter} alt="The kitchen with new wooden cabinets" />
        }
      />
      <ButtonGroup aria-label="Move the divider">
        <Button intent="secondary" onClick={() => setPosition(100)}>
          All before
        </Button>
        <Button intent="secondary" onClick={() => setPosition(50)}>
          Half
        </Button>
        <Button intent="secondary" onClick={() => setPosition(0)}>
          All after
        </Button>
      </ButtonGroup>
      <p style={{ margin: 0, color: "var(--color-muted-foreground)" }}>
        {Math.round(position)}% before
      </p>
    </div>
  );
}
```

## Vertical

With `orientation="vertical"`, before is on top and after below, and the divider moves up and down.

```tsx
import { Compare } from "@nuvui/react";
import { dashboardAfter, dashboardBefore } from "./pictures";

export default function Example() {
  return (
    <div style={{ width: "100%", maxWidth: 560 }}>
      <Compare
        orientation="vertical"
        beforeLabel="Old"
        afterLabel="New"
        dividerLabel="Old and new dashboard"
        before={<img src={dashboardBefore} alt="The old dashboard, a table" />}
        after={
          <img
            src={dashboardAfter}
            alt="The new dashboard, with three figures and a bar chart"
          />
        }
      />
    </div>
  );
}
```

## A switch

With `mode="toggle"`, there's no divider. One picture shows at a time, with a switch under it to choose the other, and the change wipes across from one to the other. It's for pictures where a half of each says little, and for anyone who finds dragging hard. `shown`, `defaultShown` and `onShownChange` work as `position` does.

```tsx
import { Compare } from "@nuvui/react";
import { kitchenAfter, kitchenBefore } from "./pictures";

export default function Example() {
  return (
    <div style={{ width: "100%", maxWidth: 560 }}>
      <Compare
        mode="toggle"
        switchLabel="Show the kitchen"
        before={
          <img src={kitchenBefore} alt="The kitchen with its old cabinets" />
        }
        after={
          <img src={kitchenAfter} alt="The kitchen with new wooden cabinets" />
        }
      />
    </div>
  );
}
```

The picture a switch hides is hidden from screen readers too, and nothing in it can take focus.

