## Checkable items

```tsx
"use client";

import {
  ContextMenu,
  ContextMenuCheckboxItem,
  ContextMenuContent,
  ContextMenuLabel,
  ContextMenuRadioGroup,
  ContextMenuRadioItem,
  ContextMenuSeparator,
  ContextMenuTrigger,
} from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [hidden, setHidden] = useState(false);
  const [sort, setSort] = useState("name");

  return (
    <ContextMenu>
      <ContextMenuTrigger
        style={{
          display: "grid",
          placeItems: "center",
          inlineSize: "min(100%, 18rem)",
          blockSize: "7rem",
          border: "1px dashed var(--color-border)",
          borderRadius: "var(--radius-lg)",
          fontSize: 14,
        }}
      >
        Sorted by {sort}
        {hidden ? ", hidden files shown" : ""}
      </ContextMenuTrigger>
      <ContextMenuContent aria-label="View">
        <ContextMenuCheckboxItem checked={hidden} onCheckedChange={setHidden}>
          Show hidden files
        </ContextMenuCheckboxItem>
        <ContextMenuSeparator />
        <ContextMenuRadioGroup value={sort} onValueChange={setSort}>
          <ContextMenuLabel>Sort by</ContextMenuLabel>
          <ContextMenuRadioItem value="name">Name</ContextMenuRadioItem>
          <ContextMenuRadioItem value="date">Date</ContextMenuRadioItem>
          <ContextMenuRadioItem value="size">Size</ContextMenuRadioItem>
        </ContextMenuRadioGroup>
      </ContextMenuContent>
    </ContextMenu>
  );
}
```

## Sizes

```tsx
import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
  DialogTrigger,
} from "@nuvui/react";

const sizes = ["sm", "md", "lg"] as const;

export default function Example() {
  return (
    <>
      {sizes.map((size) => (
        <Dialog key={size}>
          <DialogTrigger asChild>
            <Button intent="secondary">Open {size}</Button>
          </DialogTrigger>
          <DialogContent size={size}>
            <DialogTitle>Size {size}</DialogTitle>
            <DialogDescription>
              On a phone every size is the same full-width sheet. The sizes only
              differ once there's room to center the dialog.
            </DialogDescription>
          </DialogContent>
        </Dialog>
      ))}
    </>
  );
}
```

`size` sets the maximum width once the screen is at least 40rem wide: 24rem for `sm`, 32rem for `md` and 48rem for `lg`. Below that, the dialog is a sheet across the bottom of the screen whatever the size.

It's never taller than the screen. If the content is longer, it scrolls. [Long content](#long-content) covers which part does.

## Controlling it yourself

Pass `open` and `onOpenChange` when something else decides when the dialog closes, such as a save that has to finish first.

```tsx
"use client";

import {
  Button,
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogTitle,
  DialogTrigger,
} from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  async function save() {
    setSaving(true);
    // Stands in for a request to your server.
    await new Promise((resolve) => setTimeout(resolve, 600));
    setSaving(false);
    setOpen(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>Rename project</Button>
      </DialogTrigger>
      <DialogContent>
        <DialogTitle>Rename project</DialogTitle>
        <DialogDescription>
          The dialog stays open until the save has finished.
        </DialogDescription>
        <DialogFooter>
          <Button intent="secondary" onClick={() => setOpen(false)}>
            Cancel
          </Button>
          <Button disabled={saving} onClick={save}>
            {saving ? "Saving" : "Save"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
```

## Errors

Pass the message to `FieldError`. While it's empty it renders nothing, so there's no need to render it conditionally. While it has something in it, the control is marked invalid and described by it.

```tsx
"use client";

import {
  Button,
  Field,
  FieldControl,
  FieldDescription,
  FieldError,
  FieldLabel,
  Input,
} from "@nuvui/react";
import { type FormEvent, useState } from "react";

export default function Example() {
  const [error, setError] = useState("");

  function check(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const name = new FormData(event.currentTarget).get("workspace");
    setError(
      /^[a-z0-9-]{3,}$/.test(String(name))
        ? ""
        : "Use at least 3 lowercase letters, digits or hyphens.",
    );
  }

  return (
    <form
      // The browser's own checks are off, so the message below is the only one.
      noValidate
      onSubmit={check}
      style={{
        display: "grid",
        gap: 16,
        inlineSize: "100%",
        maxInlineSize: 320,
      }}
    >
      <Field required>
        <FieldLabel>Workspace name</FieldLabel>
        <FieldControl>
          <Input name="workspace" defaultValue="My Team" />
        </FieldControl>
        <FieldDescription>It becomes part of your address.</FieldDescription>
        <FieldError>{error}</FieldError>
      </Field>
      <Button type="submit">Create workspace</Button>
    </form>
  );
}
```

`invalid` on `Field` overrides that either way: `invalid` with no message, or `invalid={false}` to show a message without marking the control yet.

The message isn't a live region. A screen reader reads it when focus is on the control, as part of the control's description. So when a form is submitted with errors, move focus to the first invalid control. If your messages appear while someone is still typing in the field, add `role="alert"` or `aria-live="polite"` to `FieldError` so the change is announced.

## Limits

`accept`, `maxSize` and `maxFiles` decide which files are kept. A file that fails one isn't added, and nothing is shown for it: `onReject` is called with the files and a reason for each, and what to tell the person is up to you.

```tsx
"use client";

import {
  Field,
  FieldControl,
  FieldDescription,
  FieldError,
  FieldLabel,
  type FileRejection,
  FileUpload,
} from "@nuvui/react";
import { useState } from "react";

const megabyte = 1024 * 1024;

const reasons = {
  type: "isn't a PNG or JPEG image",
  size: "is over 2 MB",
  count: "is one more than the three allowed",
};

export default function Example() {
  const [rejected, setRejected] = useState<FileRejection[]>([]);

  return (
    <Field style={{ inlineSize: "100%", maxInlineSize: 420 }}>
      <FieldLabel>Product photos</FieldLabel>
      <FieldControl>
        <FileUpload
          multiple
          accept="image/png,image/jpeg"
          maxSize={2 * megabyte}
          maxFiles={3}
          onReject={setRejected}
          // A change that goes through clears the last complaint.
          onFilesChange={() => setRejected([])}
        >
          Drop up to three photos here, or choose them from your device
        </FileUpload>
      </FieldControl>
      <FieldDescription>PNG or JPEG, up to 2 MB each.</FieldDescription>
      <FieldError>
        {rejected.length > 0
          ? rejected
              .map(({ file, reason }) => `${file.name} ${reasons[reason]}.`)
              .join(" ")
          : null}
      </FieldError>
    </Field>
  );
}
```

The browser's picker already hides files that `accept` doesn't allow. A drop doesn't go through the picker, so the component checks dropped files against `accept` itself.

A file with the same name, size and date as one already in the list is ignored and isn't reported.

## Languages and regions

`locale` is a BCP 47 tag. The same number and the same props give each region its own digits, separators and place for the currency.

```tsx
import { FormattedNumber } from "@nuvui/react";

const places = [
  { locale: "en-US", currency: "USD", name: "United States" },
  { locale: "de-DE", currency: "EUR", name: "Germany" },
  { locale: "fr-CH", currency: "CHF", name: "Switzerland, in French" },
  { locale: "en-IN", currency: "INR", name: "India" },
  { locale: "ja-JP", currency: "JPY", name: "Japan" },
];

export default function Example() {
  return (
    <dl
      style={{
        display: "grid",
        gridTemplateColumns: "auto auto",
        gap: "0.5rem 2rem",
        margin: 0,
      }}
    >
      {places.map(({ locale, currency, name }) => (
        <div key={locale} style={{ display: "contents" }}>
          <dt>{name}</dt>
          <dd style={{ margin: 0, textAlign: "end" }}>
            <FormattedNumber
              value={1234567.5}
              locale={locale}
              currency={currency}
            />
          </dd>
        </div>
      ))}
    </dl>
  );
}
```

The default is `"en-US"`, and not the visitor's own language. A page is written once on the server and again in the browser, and the two can disagree about the visitor's language. React then reports that the two texts don't match. Pass the locale your app already knows, from its router or its translation library, to every number.

## As text

`formatNumber` gives the same text as a string, with the same options. It's for the places a component can't go: an `aria-label`, the axis of a chart, a page's title.

```tsx
import { formatNumber, Progress } from "@nuvui/react";

const used = 37.4;
const total = 50;

export default function Example() {
  const unit = { options: { style: "unit", unit: "gigabyte" } } as const;

  return (
    <div style={{ display: "grid", gap: "0.5rem", width: "16rem" }}>
      <Progress
        value={(used / total) * 100}
        aria-label={`Storage: ${formatNumber(used, unit)} of ${formatNumber(total, unit)} used`}
      />
      <span>
        {formatNumber(used, unit)} of {formatNumber(total, unit)}
      </span>
    </div>
  );
}
```

A unit, as here, goes through `options`, which takes anything `Intl.NumberFormat` does.

## Your own look

How far it tilts, its corners and the shine are CSS variables. The shine's colored band is the theme's primary, success, warning and danger colors unless you give it a gradient of your own.

```tsx
import { HoloCard } from "@nuvui/react";
import type { CSSProperties } from "react";

// A steeper tilt, square corners, words that rise further, and a foil
// of one color where the default has the theme's four.
const look = {
  "--nuv-holo-card-bg": "var(--color-surface)",
  "--nuv-holo-card-fg": "var(--color-surface-foreground)",
  "--nuv-holo-card-lift": "2.5rem",
  "--nuv-holo-card-tilt": "14deg",
  "--nuv-holo-card-radius": "var(--radius-sm)",
  "--nuv-holo-card-foil":
    "linear-gradient(115deg, transparent 30%, var(--color-warning) 50%, transparent 70%)",
  inlineSize: "100%",
  maxInlineSize: 340,
} as CSSProperties;

export default function Example() {
  return (
    <HoloCard style={{ ...look, boxShadow: "0 0 0 1px var(--color-border)" }}>
      <div
        style={{
          display: "grid",
          gap: 8,
          padding: 24,
        }}
      >
        <span
          style={{
            color: "var(--color-muted-foreground)",
            fontSize: "var(--text-sm)",
          }}
        >
          Sales kickoff 2027
        </span>
        <strong style={{ fontSize: "var(--text-xl)" }}>Speaker</strong>
        <span>Tom Becker, Finance</span>
      </div>
    </HoloCard>
  );
}
```

