          width="16"
          height="16"
          fill="none"
          stroke="currentColor"
          strokeWidth="1.5"
          strokeLinecap="round"
        >
          <circle cx="7" cy="7" r="4.5" />
          <path d="M10.5 10.5L14 14" />
        </svg>
      </InputGroupAddon>
      <Input
        ref={input}
        aria-label="Search"
        value={query}
        onChange={(event) => setQuery(event.target.value)}
      />
      {query ? (
        <InputGroupButton
          aria-label="Clear search"
          onClick={() => {
            setQuery("");
