## Controlling it yourself

```tsx
"use client";

import { RadioGroup, RadioGroupItem } from "@nuvui/react";
import { useState } from "react";

const row = { display: "flex", alignItems: "center", gap: 8 };
const prices = { month: "$12 a month", year: "$120 a year" };

export default function Example() {
  const [period, setPeriod] = useState<keyof typeof prices>("month");

  return (
    <div style={{ display: "grid", gap: 16 }}>
      <RadioGroup
        aria-label="Billing period"
        value={period}
        onValueChange={(value) => setPeriod(value as keyof typeof prices)}
      >
        <div style={row}>
          <RadioGroupItem value="month" id="radio-month" />
          <label htmlFor="radio-month">Monthly</label>
        </div>
        <div style={row}>
          <RadioGroupItem value="year" id="radio-year" />
          <label htmlFor="radio-year">Yearly</label>
        </div>
      </RadioGroup>
      <output aria-live="polite">You pay {prices[period]}.</output>
    </div>
  );
}
```

## Showing a rating

`readOnly` is for a rating nobody changes here: an average, or someone else's review. The value can have a fraction, and the star it falls in is filled that far.

```tsx
import { Rating } from "@nuvui/react";

const products = [
  { name: "Standing desk", average: 4.5, reviews: 128 },
  { name: "Monitor arm", average: 3.7, reviews: 64 },
  { name: "Cable tray", average: 2, reviews: 9 },
];

export default function Example() {
  return (
    <ul
      style={{
        display: "grid",
        gap: 12,
        margin: 0,
        padding: 0,
        listStyle: "none",
      }}
    >
      {products.map((product) => (
        <li
          key={product.name}
          style={{ display: "flex", gap: 12, alignItems: "center" }}
        >
          <span style={{ inlineSize: "8rem" }}>{product.name}</span>
          <Rating readOnly size="sm" value={product.average} />
          <span>
            {product.average} ({product.reviews})
          </span>
        </li>
      ))}
    </ul>
  );
}
```

A read-only rating is one picture to a screen reader, named "4.5 out of 5". It isn't a set of disabled controls, which would be read one star at a time and say nothing of the half. Put the number beside it as text when it matters: part of a star is hard to judge by eye.

## Sizes, and more stars

`size` changes the stars, and `max` how many there are.

```tsx
import { Rating } from "@nuvui/react";

export default function Example() {
  return (
    <div style={{ display: "grid", gap: 12, justifyItems: "center" }}>
      <Rating size="sm" defaultValue={4} aria-label="Small" />
      <Rating size="md" defaultValue={4} aria-label="Medium" />
      <Rating size="lg" defaultValue={4} aria-label="Large" />
      <Rating max={10} defaultValue={7} aria-label="Out of ten" />
    </div>
  );
}
```

## One above another

```tsx
import { Resizable, ResizableHandle, ResizablePanel } from "@nuvui/react";

const pane = { padding: 16 };

export default function Example() {
  return (
    <div
      style={{
        inlineSize: "100%",
        blockSize: 280,
        border: "1px solid var(--color-border)",
        borderRadius: "var(--radius-lg)",
        overflow: "hidden",
      }}
    >
      <Resizable orientation="vertical">
        <ResizablePanel defaultSize="60%" minSize="25%" style={pane}>
          Query
        </ResizablePanel>
        <ResizableHandle aria-label="Resize query" />
        <ResizablePanel minSize="25%" style={pane}>
          Results
        </ResizablePanel>
      </Resizable>
    </div>
  );
}
```

## A panel that folds away

A `collapsible` panel folds to nothing when it's dragged to well under its `minSize`, and opens again when it's dragged back. Enter on the handle after it does the same.

To fold it from a button, take a ref with `useResizablePanelRef` and give it to the panel as `panelRef`. It has `collapse`, `expand`, `isCollapsed`, `resize` and `getSize`.

```tsx
"use client";

import {
  Button,
  Resizable,
  ResizableHandle,
  ResizablePanel,
  useResizablePanelRef,
} from "@nuvui/react";
import { useState } from "react";

const pane = { padding: 16 };

export default function Example() {
  const panel = useResizablePanelRef();
  const [folded, setFolded] = useState(false);

  return (
    <div style={{ display: "grid", gap: 12, inlineSize: "100%" }}>
      <div>
        <Button
          size="sm"
          intent="secondary"
          aria-expanded={!folded}
          aria-controls="resizable-example-nav"
          onClick={() =>
            folded ? panel.current?.expand() : panel.current?.collapse()
          }
        >
          {folded ? "Show navigation" : "Hide navigation"}
        </Button>
      </div>
      <div
        style={{
          blockSize: 220,
          border: "1px solid var(--color-border)",
          borderRadius: "var(--radius-lg)",
          overflow: "hidden",
        }}
      >
        <Resizable>
          <ResizablePanel
            id="resizable-example-nav"
            panelRef={panel}
            collapsible
            defaultSize="30%"
            minSize="20%"
            onResize={(size) => setFolded(size.asPercentage === 0)}
            style={pane}
          >
            Navigation
          </ResizablePanel>
          <ResizableHandle aria-label="Resize navigation" />
          <ResizablePanel minSize="40%" style={pane}>
            Page
          </ResizablePanel>
        </Resizable>
      </div>
    </div>
  );
}
```

A panel folded to nothing still has its content in the page. It's made `inert` while there's no room for it, so Tab and a screen reader pass it by. `collapsedSize` leaves some of the panel showing, for a rail of icons, and then what's in it stays in reach.

## Remembering the sizes

`useResizableLayout` keeps the sizes in the browser's `localStorage` under a name, and gives them back on the next visit. It does without, quietly, where storage is missing or refused. Each panel needs an `id`, which is what its size is kept under. Resize these and load the page again.

```tsx
"use client";

import {
  Resizable,
  ResizableHandle,
  ResizablePanel,
  useResizableLayout,
} from "@nuvui/react";

const pane = { padding: 16 };

export default function Example() {
  // Kept in the browser's own storage, under this name.
  const { defaultLayout, onLayoutChanged } = useResizableLayout({
    id: "docs-resizable-saved",
  });

  return (
    <div
      style={{
        inlineSize: "100%",
        blockSize: 220,
        border: "1px solid var(--color-border)",
        borderRadius: "var(--radius-lg)",
        overflow: "hidden",
      }}
    >
      <Resizable
        defaultLayout={defaultLayout}
        onLayoutChanged={onLayoutChanged}
      >
        <ResizablePanel id="list" minSize="20%" style={pane}>
          List
        </ResizablePanel>
        <ResizableHandle withGrip aria-label="Resize list" />
        <ResizablePanel id="detail" minSize="20%" style={pane}>
          Detail
        </ResizablePanel>
      </Resizable>
    </div>
  );
}
```

It takes a `storage` of your own, anything with `getItem` and `setItem`, for keeping them in a cookie or on your server. To save them yourself, `onLayoutChanged` is called with every panel's size once a drag has ended. `onLayoutChange`, without the d, is called all through the drag.

A page drawn on a server doesn't know what the browser kept, so it draws the default sizes and the kept ones are put in place once the browser has the page. With a `storage` of yours that reads a cookie, the server knows them too, and nothing moves.

## Give it a height

A scroll area scrolls once its content is taller than it is, so it needs a height, or a maximum. Set either with `style`, with a class, or with `--nuv-scroll-area-height` and `--nuv-scroll-area-max-height`.

With only a maximum, a short list stays short and a long one stops growing and starts to scroll.

```tsx
"use client";

import { Button, ScrollArea } from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [count, setCount] = useState(3);

  return (
    <div style={{ display: "grid", gap: 12, width: "100%", maxWidth: 260 }}>
      <Button intent="secondary" size="sm" onClick={() => setCount(count + 3)}>
        Add three rows
      </Button>
      <ScrollArea
        aria-label="Rows"
        style={{
          maxHeight: "10rem",
          border: "1px solid var(--color-border)",
          borderRadius: "var(--radius-lg)",
        }}
      >
        <ul
          style={{
            margin: 0,
            padding: "8px 16px",
            listStyle: "none",
            fontSize: 14,
          }}
        >
          {Array.from({ length: count }, (_, index) => `Row ${index + 1}`).map(
            (row) => (
              <li key={row} style={{ paddingBlock: 6 }}>
                {row}
              </li>
            ),
          )}
        </ul>
      </ScrollArea>
    </div>
  );
}
```

## Sideways

`orientation="horizontal"` scrolls sideways and puts the scrollbar along the bottom. `"both"` scrolls each way.

```tsx
import { ScrollArea } from "@nuvui/react";

const months = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
];

export default function Example() {
  return (
    <ScrollArea
      orientation="horizontal"
      aria-label="Months"
      style={{ width: "100%", maxWidth: 360 }}
    >
      <div style={{ display: "flex", gap: 12, paddingBlockEnd: 16 }}>
        {months.map((month) => (
          <div
            key={month}
            style={{
              flex: "none",
              width: 120,
              padding: 16,
              border: "1px solid var(--color-border)",
              borderRadius: "var(--radius-lg)",
              fontSize: 14,
            }}
          >
            {month}
          </div>
        ))}
      </div>
    </ScrollArea>
  );
}
```

With `"vertical"`, long lines wrap and the area never scrolls sideways. With the other two, content is laid out at its full width, which is what makes it scroll.

Leave room for the bar. It's drawn over the content's edge, 10 pixels thick, so content that runs right up to that edge sits under it. The example above has padding at the bottom for that.

## Controlling it yourself

```tsx
"use client";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@nuvui/react";
import { useState } from "react";

const sizes = { s: "Small", m: "Medium", l: "Large" };

export default function Example() {
  const [size, setSize] = useState("m");

  return (
    <div style={{ display: "grid", gap: 6 }}>
      <label htmlFor="size">Size</label>
      <Select value={size} onValueChange={setSize}>
        <SelectTrigger id="size">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {Object.entries(sizes).map(([value, name]) => (
            <SelectItem key={value} value={value}>
              {name}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
      <p style={{ margin: 0 }}>The value is "{size}".</p>
    </div>
  );
}
```

## In a sentence

`variant="inline"` on the trigger is a select with no box, for a choice that reads as part of a sentence: "164 orders in the last 30 days". It takes the size, the weight and the color of the text around it, and is as wide as the option it shows.

```tsx
"use client";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@nuvui/react";
import { useState } from "react";

const counts: Record<string, number> = { "7": 38, "30": 164, "365": 1912 };

export default function Example() {
  const [period, setPeriod] = useState("30");

  return (
    <p style={{ margin: 0, fontSize: 18 }}>
      <span aria-live="polite">{counts[period]} orders</span> in{" "}
      <Select value={period} onValueChange={setPeriod}>
        <SelectTrigger variant="inline" aria-label="Period">
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          <SelectItem value="7">the last 7 days</SelectItem>
          <SelectItem value="30">the last 30 days</SelectItem>
          <SelectItem value="365">the last year</SelectItem>
        </SelectContent>
      </Select>
      .
    </p>
  );
}
```

It has no label beside it, so name it with `aria-label`. Keep it to one in a sentence, or two: every one is a stop for the eye, and a sentence full of them is a form.

## Vertical

An upright separator is as tall as the row it's in, when that row is a flex or grid container. Anywhere else it's as tall as a letter.

```tsx
import { Separator } from "@nuvui/react";

export default function Example() {
  return (
    <div
      style={{ display: "flex", gap: 12, alignItems: "center", fontSize: 14 }}
    >
      <span>Docs</span>
      <Separator orientation="vertical" />
      <span>Components</span>
      <Separator orientation="vertical" />
      <span>Changelog</span>
    </div>
  );
}
```

## Decorative, or not

By default a separator is decoration. It has `role="none"`, and a screen reader says nothing for it. That's right for nearly every line on a page: the headings and lists around it already say where one thing ends and the next begins.

Pass `decorative={false}` where the line is the only thing that marks a change, such as a break between two parts of a text with no heading for the second. It then has `role="separator"`, and a screen reader announces it.

```tsx
import { Separator } from "@nuvui/react";

export default function Example() {
  return (
    <div style={{ width: "100%", maxWidth: 320, fontSize: 14 }}>
      <p style={{ margin: 0 }}>The order was packed on Monday.</p>
      <Separator decorative={false} style={{ marginBlock: 12 }} />
      <p style={{ margin: 0 }}>A week later, nothing had arrived.</p>
    </div>
  );
}
```

Radix's own default is the other way round. This library flips it, because a line that's announced when it means nothing adds a stop to every pass through the page.

## Sides

```tsx
import {
  Button,
  Sheet,
  SheetContent,
  SheetDescription,
  SheetTitle,
  SheetTrigger,
} from "@nuvui/react";

const sides = ["start", "end", "top", "bottom"] as const;

export default function Example() {
  return (
    <>
      {sides.map((side) => (
        <Sheet key={side}>
          <SheetTrigger asChild>
            <Button intent="secondary">{side}</Button>
          </SheetTrigger>
          <SheetContent side={side}>
            <SheetTitle>On the {side} edge</SheetTitle>
            <SheetDescription>
              Press Escape, the close button or the page behind to close it.
            </SheetDescription>
          </SheetContent>
        </Sheet>
      ))}
    </>
  );
}
```

`side` names the edge. `"start"` and `"end"` follow the reading direction: `"end"` is the right edge in a left-to-right layout and the left edge in a right-to-left one. The sheet slides in from the edge it's on.

A sheet on the top or bottom edge is as wide as the screen and as tall as what it holds. It stops 48 pixels short of the full height, and its body scrolls from there.

## Stops

`stops` is a list of sizes the sheet rests at, each a share of the screen: `[0.35, 0.9]` is a sheet that opens a third of the way up and can be pulled nearly to the top. Dragging changes its size under the finger, and letting go settles it on the nearest stop. Dragged well under the smallest, it closes.

```tsx
"use client";

import {
  Button,
  Sheet,
  SheetBody,
  SheetContent,
  SheetHandle,
  SheetHeader,
  SheetTitle,
  SheetTrigger,
} from "@nuvui/react";
import { useState } from "react";

const stops = [0.35, 0.9];

const orders = Array.from({ length: 24 }, (_, index) => ({
  id: `ORD-${7231 - index}`,
  total: 40 + ((index * 37) % 260),
}));

export default function Example() {
  const [stop, setStop] = useState(stops[0]);

  return (
    <Sheet>
      <SheetTrigger asChild>
        <Button intent="secondary">Recent orders</Button>
      </SheetTrigger>
      <SheetContent
        side="bottom"
        stops={stops}
        stop={stop}
        onStopChange={setStop}
        aria-describedby={undefined}
      >
        <SheetHandle />
        <SheetHeader>
          <SheetTitle>Recent orders</SheetTitle>
        </SheetHeader>
        <SheetBody>
          <ul style={{ margin: 0, padding: 0, listStyle: "none" }}>
            {orders.map((order) => (
              <li
                key={order.id}
                style={{
                  display: "flex",
                  justifyContent: "space-between",
                  paddingBlock: 8,
                }}
              >
                <span>{order.id}</span>
                <span>${order.total}.00</span>
              </li>
            ))}
          </ul>
        </SheetBody>
      </SheetContent>
    </Sheet>
  );
}
```

The sheet is the height of its stop, not as tall as its content, so what's in it has to scroll: put it in a `SheetBody`.

`stop` and `onStopChange` control which one it's at, and `defaultStop` sets where it opens. With stops, `swipe` is on unless you turn it off.

## Remembering the state

When the sidebar is collapsed or expanded, the provider writes `true` or `false` to a cookie named `nuv-sidebar`. The next time the page loads, it reads the cookie and starts in that state.

On a server, read the cookie yourself and pass what it says as `defaultOpen`. The page then arrives in the right state, where otherwise it would arrive expanded and collapse once the script has run. In Next.js:

```tsx
import { cookies } from "next/headers";

export default async function Layout({ children }) {
  const remembered = (await cookies()).get("nuv-sidebar")?.value;

  return (
    <SidebarProvider defaultOpen={remembered !== "false"}>
      ...
    </SidebarProvider>
  );
}
```

`cookieName` changes the name, and `cookieName={null}` stores nothing. The cookie lasts a year, is sent to every path, and holds nothing but that one word. Whether it needs a mention in your cookie notice is a question for your own policy. It's a setting the person chose, not tracking.

The first example on this page is the only one that writes the cookie. Collapse it and reload the page.

## Colors

The sidebar takes the surface colors. Every row's fill is worked out from its text color, so it holds on any background.

```css title="themed.css"
/* The primary color as the background. The text and the group label take
   the color that's made to be read on it. */
.brand-sidebar {
  --nuv-sidebar-bg: var(--color-primary);
  --nuv-sidebar-fg: var(--color-primary-foreground);
  --nuv-sidebar-muted-fg: var(--color-primary-foreground);
  --nuv-sidebar-border: var(--color-primary);
  --nuv-focus-ring-color: var(--color-primary-foreground);

  /* The fills a row gets by default are a little of the text color mixed
     in, which on a color this strong would bring the two too close to
     read. These go the other way: away from the text. */
  --nuv-sidebar-item-bg-hover: color-mix(
    in oklab,
    var(--color-primary) 88%,
    oklch(from var(--color-primary-foreground) calc(1 - l) 0 0)
  );
  --nuv-sidebar-item-bg-active: color-mix(
    in oklab,
    var(--color-primary) 80%,
    oklch(from var(--color-primary-foreground) calc(1 - l) 0 0)
  );
}
```

```tsx
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupLabel,
  SidebarMain,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarProvider,
  SidebarTrigger,
} from "@nuvui/react";
import type { CSSProperties } from "react";
import "./themed.css";

const pages = ["Overview", "Deployments", "Logs", "Billing"];

function Menu() {
  return (
    <SidebarContent>
      <SidebarGroup>
        <SidebarGroupLabel>Project</SidebarGroupLabel>
        <SidebarMenu>
          {pages.map((page, index) => (
            <SidebarMenuItem key={page}>
              <SidebarMenuButton asChild active={index === 0}>
                <a href={`#${page.toLowerCase()}`}>{page}</a>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroup>
    </SidebarContent>
  );
}

const box = {
  "--nuv-sidebar-height": "16rem",
  "--nuv-sidebar-width": "11rem",
  border: "1px solid var(--color-border)",
  borderRadius: "var(--radius-lg)",
  overflow: "hidden",
} as CSSProperties;

export default function Example() {
  return (
    <div style={{ display: "grid", gap: 16, inlineSize: "100%" }}>
      <SidebarProvider cookieName={null} shortcut={null} style={box}>
        {/* Dark, even while the page is light. */}
        <Sidebar label="Dark sidebar" collapsible="offcanvas" data-theme="dark">
          <Menu />
        </Sidebar>
        <SidebarMain asChild>
          <div style={{ padding: 16 }}>
            <SidebarTrigger label="Toggle the dark sidebar" />
          </div>
        </SidebarMain>
      </SidebarProvider>
      <SidebarProvider cookieName={null} shortcut={null} style={box}>
        <Sidebar
          label="Brand sidebar"
          collapsible="offcanvas"
          className="brand-sidebar"
        >
          <Menu />
        </Sidebar>
        <SidebarMain asChild>
          <div style={{ padding: 16 }}>
            <SidebarTrigger label="Toggle the brand sidebar" />
          </div>
        </SidebarMain>
      </SidebarProvider>
    </div>
  );
}
```

For a dark sidebar in a light app, put `data-theme="dark"` on `Sidebar`. Everything inside takes the dark theme's colors, with the contrast that theme was checked for.

For a background of your own, set `--nuv-sidebar-bg` and `--nuv-sidebar-fg`. On a strong color such as the brand color, set the two row fills as well. By default a row under the pointer is filled with a little of the text color, which on a mid-tone background brings the text and the fill too close together to read. The stylesheet above mixes away from the text color.

## In place of real content

Render the skeletons in the same parts the content will use, and swap one for the other when the data arrives.

```tsx
"use client";

import {
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Skeleton,
  VisuallyHidden,
} from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [loading, setLoading] = useState(true);

  return (
    <div
      style={{
        display: "grid",
        gap: 12,
        justifyItems: "start",
        width: "100%",
        maxWidth: 360,
      }}
    >
      <Button intent="secondary" onClick={() => setLoading((value) => !value)}>
        {loading ? "Finish loading" : "Load again"}
      </Button>
      <Card aria-busy={loading} style={{ width: "100%" }}>
        {loading ? (
          <>
            <CardHeader>
              <Skeleton shape="text" style={{ width: "45%" }} />
              <Skeleton shape="text" style={{ width: "70%" }} />
            </CardHeader>
            <CardContent>
              <Skeleton style={{ height: 64 }} />
            </CardContent>
          </>
        ) : (
          <>
            <CardHeader>
              <CardTitle>Northwind Traders</CardTitle>
              <CardDescription>Customer since March 2021</CardDescription>
            </CardHeader>
            <CardContent>
              Fourteen orders this year, the last one on 4 July. Nothing is
              overdue.
            </CardContent>
          </>
        )}
      </Card>
      {/* Says when the content has arrived. The skeletons themselves are
          hidden from screen readers. */}
      <VisuallyHidden role="status">
        {loading ? "Loading the customer" : "The customer has loaded"}
      </VisuallyHidden>
    </div>
  );
}
```

## A range

Two values draw two handles, and the part between them is filled. `minStepsBetweenThumbs` keeps one from landing on the other.

```tsx
"use client";

import { Label, Slider } from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [price, setPrice] = useState([200, 600]);

  return (
    <div
      style={{
        display: "grid",
        gap: 8,
        inlineSize: "100%",
        maxInlineSize: 320,
      }}
    >
      <div style={{ display: "flex", justifyContent: "space-between" }}>
        <Label asChild>
          <span id="slider-price">Price</span>
        </Label>
        <output>
          ${price[0]} to ${price[1]}
        </output>
      </div>
      <Slider
        aria-labelledby="slider-price"
        thumbLabels={["Lowest price", "Highest price"]}
        min={0}
        max={1000}
        step={50}
        minStepsBetweenThumbs={1}
        value={price}
        onValueChange={setPrice}
      />
    </div>
  );
}
```

With two handles, the slider's name goes to the group and each handle needs one of its own. Radix calls them "Minimum" and "Maximum". Set `thumbLabels` to say something more exact, or to translate them.

## Vertical

```tsx
import { Slider } from "@nuvui/react";

export default function Example() {
  return (
    <div style={{ display: "flex", gap: 32 }}>
      <Slider aria-label="Bass" orientation="vertical" defaultValue={[60]} />
      <Slider aria-label="Mid" orientation="vertical" defaultValue={[45]} />
      <Slider aria-label="Treble" orientation="vertical" defaultValue={[70]} />
    </div>
  );
}
```

A vertical slider is 10rem tall. Set `--nuv-slider-length` to change that.

