    >
      <Label htmlFor="picker-termin">Termin</Label>
      <DatePicker
        id="picker-termin"
        locale={de}
        placeholder="TT.MM.JJJJ"
        calendarLabel="Datum wählen"
        title="Datum wählen"
        closeLabel="Schließen"
        invalidMessage="Geben Sie ein gültiges Datum ein."
      />
    </div>
  );
}
```

## Time zones

With `timeZone`, the day is a day in that place. The date you get back is midnight there, and the form value is the day there, whatever the browser's own zone is.

```tsx
"use client";

import { DatePicker } from "@nuvui/date-picker";
import { Label } from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [date, setDate] = useState<Date | null>(null);

  return (
    <div
      style={{
        display: "grid",
        gap: 6,
        inlineSize: "100%",
        maxInlineSize: 280,
      }}
    >
      <Label htmlFor="picker-tokyo">Launch day in Tokyo</Label>
      <DatePicker
        id="picker-tokyo"
        timeZone="Asia/Tokyo"
        value={date}
        onValueChange={setDate}
      />
      <p style={{ margin: 0, fontSize: 14 }}>
        {date
          ? `Midnight in Tokyo is ${new Date(date.getTime()).toISOString()} in UTC.`
          : "No date picked."}
      </p>
    </div>
  );
}
```

[Dates](page:date-picker/index#time-zones) says when to use it and how to pass `min` and `max`.

## In a form

`startName` and `endName` are the names the two days are submitted under, each as `yyyy-MM-dd`.

Inside a [field](page:components/field), wrap the picker in `FieldControl`. The label names the group, a click on it goes to the first field, and the description and the error are read with both.

```tsx
"use client";

import { type DateRange, DateRangePicker } from "@nuvui/date-picker";
import {
  Button,
  Field,
  FieldControl,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [range, setRange] = useState<DateRange | null>(null);
  const [sent, setSent] = useState<string | undefined>();
  const [submitted, setSubmitted] = useState(false);
  const complete = Boolean(range?.from && range.to);
  const error = submitted && !complete ? "Enter both dates." : undefined;

  return (
    <form
      noValidate
      style={{ display: "grid", gap: 16, width: "100%", maxWidth: 340 }}
      onSubmit={(event) => {
        event.preventDefault();
        setSubmitted(true);
        const data = new FormData(event.currentTarget);
        setSent(
          complete
            ? `from=${data.get("from")} to=${data.get("to")}`
            : undefined,
        );
      }}
    >
      <Field required>
        <FieldLabel>Report period</FieldLabel>
        <FieldControl>
          <DateRangePicker
            startName="from"
            endName="to"
            max={new Date()}
            value={range}
            onValueChange={setRange}
          />
        </FieldControl>
        <FieldDescription>Up to today.</FieldDescription>
        <FieldError>{error}</FieldError>
      </Field>
      <Button type="submit">Run report</Button>
      <output style={{ fontSize: 14 }}>{sent ? `Sent: ${sent}` : null}</output>
    </form>
  );
}
```

`required` goes on both text fields. As with a date picker, a form with `noValidate` leaves the checking to you.

## The length of a range

`min`, `max` and `disabledDates` limit which days can be picked, as on a date picker. How long the range may be is a calendar option: `calendar={{ min: 2, max: 14 }}` allows from two to fourteen days between the ends.

```tsx
"use client";

import { DateRangePicker } from "@nuvui/date-picker";
import { Label } from "@nuvui/react";

const today = new Date();
today.setHours(0, 0, 0, 0);

export default function Example() {
  return (
    <div
      style={{
        display: "grid",
        gap: 6,
        inlineSize: "100%",
        maxInlineSize: 340,
      }}
    >
      <Label id="range-trip-label" htmlFor="range-trip">
        Trip
      </Label>
      <DateRangePicker
        id="range-trip"
        aria-labelledby="range-trip-label"
        min={today}
        startLabel="Check-in"
        endLabel="Check-out"
        // At least two nights and at most fourteen.
        calendar={{ min: 2, max: 14 }}
      />
    </div>
  );
}
```

A second press that would make the range too short or too long starts a new range from that day. `excludeDisabled`, also in `calendar`, does the same for a range that would run across a day that can't be picked.

The length isn't checked for typed dates. Check it in your own validation, where you can also say what the limit is.

