```tsx
import { createShikiHighlighter } from "@nuvui/chat/shiki";

// Once, outside any component.
const highlighter = createShikiHighlighter();

<Markdown highlighter={highlighter}>{text}</Markdown>;
```

## Your own elements

`components` replaces an element with one of yours, by tag name, the way react-markdown takes them. Links that open in a new tab, for one:

```tsx
const components = {
  a: ({ node, ...props }) => <a {...props} target="_blank" rel="noreferrer" />,
};

<Markdown components={components}>{text}</Markdown>;
```

Keep the object outside the component, or in a `useMemo`. A new object on every render makes every element a new one, and a block of code would lose its colors each time.

## Colors

By itself the code is in one color, and the component depends on nothing. Colors come from a `highlighter`: a function that's given the code and the language and returns the code's lines as tokens, each with a color.

One for [Shiki](https://shiki.style) is ready. Install Shiki next to the package:

```sh
pnpm add shiki
```

```tsx
import { CodeBlock } from "@nuvui/chat";
import { createShikiHighlighter } from "@nuvui/chat/shiki";

// Once for the whole app, outside any component.
const highlighter = createShikiHighlighter();

<CodeBlock code={code} language="ts" highlighter={highlighter} />;
```

Nothing of Shiki is loaded with the page. It's fetched the first time code is colored, and each language's grammar the first time that language turns up. Until then the code is in one color, and it stays that way for a language Shiki doesn't know. It uses Shiki's engine written in JavaScript, so there's no WebAssembly to serve.

While code is still arriving, what has been colored stays colored and what's new is added after it in one color until it's colored too. Nothing flickers, and the code on the screen is never behind.

### The colors are the theme's

A token's color is a CSS variable, so the code follows the theme and dark mode with nothing to switch. Without the variables set, each kind takes one of the theme's colors that's checked as text against the box's background, in every preset:

| Variable | What it colors | Default |
| --- | --- | --- |
| `--nuv-code-block-token-keyword` | Keywords and operators | `--color-danger` |
| `--nuv-code-block-token-string`, `--nuv-code-block-token-string-expression` | Text in quotes | `--color-success` |
| `--nuv-code-block-token-constant` | Numbers, constants and names that are defined | `--color-warning` |
| `--nuv-code-block-token-comment` | Comments | `--color-muted-foreground` |
| `--nuv-code-block-token-punctuation` | Brackets and commas | `--color-muted-foreground` |
| `--nuv-code-block-token-function`, `--nuv-code-block-token-parameter`, `--nuv-code-block-token-link` | Function names, parameters, links | The box's text color |
| `--nuv-code-block-token-inserted`, `--nuv-code-block-token-deleted`, `--nuv-code-block-token-changed` | Lines of a diff | `--color-success`, `--color-danger`, `--color-warning` |
| `--nuv-code-block-foreground` | Everything else | The box's text color |

Set them on the block or on anything around it. Keep each at 4.5:1 against the box's background.

```css
.chat {
  --nuv-code-block-token-function: var(--color-chart-1);
}
```

### One of your own

A highlighter is a function, so any library fits behind it:

```tsx
import type { CodeHighlighter } from "@nuvui/chat";

const highlighter: CodeHighlighter = (code, language) => {
  if (language !== "json") return null;
  return code.split("\n").map((line) => [{ content: line, color: "var(--color-success)" }]);
};
```

It returns the lines, each a list of tokens, or a promise of them. The tokens' text, put back together, has to be the code it was given. `null` says the language isn't one it knows.

## While a reply is on its way

Set `busy` from the moment something is sent until the reply is done. Nothing more can be sent until then. The field stays open, so the next message can be written while the reply arrives.

With `onStop`, the button to send becomes a button to stop for as long as the box is busy.

```tsx
"use client";

import {
  PromptInput,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputToolbar,
} from "@nuvui/chat";
import { useEffect, useRef, useState } from "react";

export default function Example() {
  const [busy, setBusy] = useState(false);
  const [said, setSaid] = useState("Nothing sent yet.");
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);

  function send(text: string) {
    setBusy(true);
    setSaid(`Replying to: ${text}`);
    // A reply that takes ten seconds, long enough to stop it.
    timer.current = setTimeout(() => {
      setBusy(false);
      setSaid("Replied.");
    }, 10_000);
  }

  function stop() {
    clearTimeout(timer.current);
    setBusy(false);
    setSaid("Stopped.");
  }

  return (
    <div
      style={{
        display: "grid",
        gap: "0.75rem",
        inlineSize: "100%",
        maxInlineSize: 520,
      }}
    >
      <PromptInput busy={busy} onStop={stop} onSubmit={send}>
        <PromptInputTextarea aria-label="Message" placeholder="Ask anything" />
        <PromptInputToolbar>
          <PromptInputSubmit />
        </PromptInputToolbar>
      </PromptInput>
      <p role="status" style={{ margin: 0 }}>
        {said}
      </p>
    </div>
  );
}
```

## Buttons in the row

`PromptInputTools` holds whatever goes with the prompt: where to look, which model, a mode. They sit at the start of the row and the button to send at the end. Give a button `type="button"`, so that pressing it doesn't send.

```tsx
"use client";

import {
  PromptInput,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputToolbar,
  PromptInputTools,
} from "@nuvui/chat";
import { Button, NativeSelect } from "@nuvui/react";
import { useState } from "react";

export default function Example() {
  const [scope, setScope] = useState("This workspace");
  const [sent, setSent] = useState("Nothing sent yet.");

  return (
    <div
      style={{
        display: "grid",
        gap: "0.75rem",
        inlineSize: "100%",
        maxInlineSize: 520,
      }}
    >
      <PromptInput onSubmit={(text) => setSent(`Asked ${scope}: ${text}`)}>
        <PromptInputTextarea aria-label="Message" placeholder="Ask anything" />
        <PromptInputToolbar>
          <PromptInputTools>
            <NativeSelect
              aria-label="Where to look"
              value={scope}
              onChange={(event) => setScope(event.target.value)}
            >
              <option>This workspace</option>
              <option>Invoices</option>
              <option>Customers</option>
            </NativeSelect>
            <Button
              type="button"
              intent="ghost"
              size="sm"
              onClick={() => setSent("Cleared.")}
            >
              Clear
            </Button>
          </PromptInputTools>
          <PromptInputSubmit />
        </PromptInputToolbar>
      </PromptInput>
      <p role="status" style={{ margin: 0 }}>
        {sent}
      </p>
    </div>
  );
}
```

## Files

Put a `PromptInputAttachments` over the field and a `PromptInputAttach` in the row, and the box takes files. They wait in it, each with a button that takes it out again, and are handed to `onSubmit` with the text.

```tsx
"use client";

import {
  PromptInput,
  PromptInputAttach,
  PromptInputAttachments,
  type PromptInputFileRejection,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputToolbar,
  PromptInputTools,
} from "@nuvui/chat";
import { useState } from "react";

const megabyte = 1024 * 1024;

const reasons = {
  type: "isn't a picture or a PDF",
  size: "is over 5 MB",
  count: "is one more than three",
};

export default function Example() {
  const [sent, setSent] = useState("Nothing sent yet.");
  const [refused, setRefused] = useState("");

  function refuse(rejections: PromptInputFileRejection[]) {
    setRefused(
      rejections
        .map(({ file, reason }) => `${file.name} ${reasons[reason]}.`)
        .join(" "),
    );
  }

  return (
    <div
      style={{
        display: "grid",
        gap: "0.75rem",
        inlineSize: "100%",
        maxInlineSize: 520,
      }}
    >
      <PromptInput
        accept="image/*,.pdf"
        maxFiles={3}
        maxFileSize={5 * megabyte}
        onFilesChange={() => setRefused("")}
        onFilesReject={refuse}
        onSubmit={(text, { files }) =>
          setSent(
            `Sent "${text}" with ${files.length === 1 ? "1 file" : `${files.length} files`}.`,
          )
        }
      >
        <PromptInputAttachments />
        <PromptInputTextarea
          aria-label="Message"
          placeholder="Ask about a file"
        />
        <PromptInputToolbar>
          <PromptInputTools>
            <PromptInputAttach />
          </PromptInputTools>
          <PromptInputSubmit />
        </PromptInputToolbar>
      </PromptInput>
      <p role="alert" style={{ margin: 0, minBlockSize: "1.5em" }}>
        {refused}
      </p>
      <p role="status" style={{ margin: 0 }}>
        {sent}
      </p>
    </div>
  );
}
```

```tsx
<PromptInput
  accept="image/*,.pdf"
  maxFiles={3}
  maxFileSize={5 * 1024 * 1024}
  onFilesReject={tellThePerson}
  onSubmit={(text, { files }) => send(text, files)}
>
  <PromptInputAttachments />
  <PromptInputTextarea aria-label="Message" />
  <PromptInputToolbar>
    <PromptInputTools>
      <PromptInputAttach />
    </PromptInputTools>
    <PromptInputSubmit />
  </PromptInputToolbar>
</PromptInput>
```

There are three ways in, and all three go through the same checks:

- **The button** opens the device's file picker.
- **Pasting** into the field, such as a screenshot. Text that's pasted stays text: cells copied from a spreadsheet come with a picture of themselves, and the picture is left out.
- **Dropping** files on the box. While files are over it, its edge is dashed.

Pasting and dropping only take files when one of the two parts is in the box. Without them the box is for text, and a file that's dropped on it is the browser's to deal with.

`accept` is written as a file input's: `"image/*,.pdf"`. `maxFiles` is the most that can wait at once and `maxFileSize` the largest one may be, in bytes. A file that's turned away isn't shown. `onFilesReject` is called with each one and the reason, `"type"`, `"size"` or `"count"`, and that's where you tell the person. The same file added twice is kept once.

With files waiting, the box can be sent with no text.

### Keeping the files yourself

Pass `files` and `onFilesChange` to hold them: to start uploading as soon as one is added, or to keep them with a draft. `defaultFiles` starts the box with some.

To show how an upload is going, give `PromptInputAttachments` a function. It's called with each file and with the way to take it out, and returns an [`Attachment`](page:chat/attachment):

```tsx
<PromptInputAttachments>
  {(file, remove) => (
    <Attachment
      name={file.name}
      size={file.size}
      uploading={uploads.get(file)?.busy}
      error={uploads.get(file)?.error}
      onRemove={remove}
    />
  )}
</PromptInputAttachments>
```

The box doesn't upload anything. It hands you `File` objects, and where they go is yours.

## Keeping the text yourself

Pass `value` and `onValueChange` to hold the text: to limit it, to keep a draft, or to put a [suggestion](page:chat/prompt-suggestion) in the box. `onValueChange` is called with an empty text after a send.

```tsx
"use client";

import {
  PromptInput,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputToolbar,
} from "@nuvui/chat";
import { useState } from "react";

const limit = 280;

export default function Example() {
  const [text, setText] = useState("");

  return (
    <div style={{ inlineSize: "100%", maxInlineSize: 520 }}>
      <PromptInput
        value={text}
        onValueChange={(next) => setText(next.slice(0, limit))}
        onSubmit={() => {}}
      >
        <PromptInputTextarea
          aria-label="Message"
          aria-describedby="prompt-left"
          placeholder="Ask anything"
        />
        <PromptInputToolbar>
          <span id="prompt-left" style={{ fontSize: "var(--text-sm)" }}>
            {limit - text.length} characters left
          </span>
          <PromptInputSubmit />
        </PromptInputToolbar>
      </PromptInput>
    </div>
  );
}
```

## In an empty conversation

Inside a [`ConversationEmpty`](page:chat/conversation#before-the-first-message) they sit in the middle, under a greeting.

```tsx
"use client";

import {
  Conversation,
  ConversationContent,
  ConversationEmpty,
  Message,
  MessageContent,
  PromptInput,
  PromptInputSubmit,
  PromptInputTextarea,
  PromptInputToolbar,
  PromptSuggestion,
  PromptSuggestions,
} from "@nuvui/chat";
import { useState } from "react";

const starters = [
  "Summarize last month's invoices",
  "Who hasn't paid yet?",
  "Draft a reminder",
];

export default function Example() {
  const [sent, setSent] = useState<string[]>([]);

  return (
    <Conversation
      style={{
        inlineSize: "100%",
        maxInlineSize: 520,
        blockSize: 380,
        border: "1px solid var(--color-border)",
        borderRadius: "var(--radius-xl)",
      }}
    >
      <ConversationContent aria-label="A new conversation">
        {sent.length === 0 ? (
          <ConversationEmpty>
            <p style={{ margin: 0, fontWeight: 600 }}>
              What do you want to know?
            </p>
            <PromptSuggestions>
              {starters.map((text) => (
                <PromptSuggestion
                  key={text}
                  onClick={() => setSent((now) => [...now, text])}
                >
                  {text}
                </PromptSuggestion>
              ))}
            </PromptSuggestions>
          </ConversationEmpty>
        ) : (
          sent.map((text, index) => (
            <Message key={index} from="user">
              <MessageContent>{text}</MessageContent>
            </Message>
          ))
        )}
      </ConversationContent>
      <div style={{ padding: "0 1rem 1rem" }}>
        <PromptInput onSubmit={(text) => setSent((now) => [...now, text])}>
          <PromptInputTextarea
            aria-label="Message"
            placeholder="Ask anything"
          />
          <PromptInputToolbar>
            <PromptInputSubmit />
          </PromptInputToolbar>
        </PromptInput>
      </div>
    </Conversation>
  );
}
```

## Waiting, uploading and failed

`onRemove` gives a file a button that takes it out. `uploading` shows a spinner where the icon was and "Uploading" where the size was. `error` takes what went wrong, in words, and shows it in place of the size.

```tsx
"use client";

import { Attachment, Attachments } from "@nuvui/chat";
import { Button } from "@nuvui/react";
import { useState } from "react";

const all = [
  { name: "contract-draft.docx", size: 48_200 },
  { name: "site-photos.zip", size: 18_400_000, uploading: true },
  {
    name: "scan-0042.tiff",
    size: 61_000_000,
    error: "Too large. The limit is 25 MB.",
  },
];

export default function Example() {
  const [files, setFiles] = useState(all);

  return (
    <div style={{ display: "grid", gap: "0.75rem", justifyItems: "start" }}>
      <Attachments aria-label="Files to send">
        {files.map((file) => (
          <Attachment
            key={file.name}
            {...file}
            onRemove={() =>
              setFiles((now) => now.filter((other) => other !== file))
            }
          />
        ))}
      </Attachments>
      <p role="status" style={{ margin: 0 }}>
        {files.length} of 3 files left.
      </p>
      <Button intent="secondary" size="sm" onClick={() => setFiles(all)}>
        Put them back
      </Button>
    </div>
  );
}
```

The prompt box draws the files that wait in it with this component, and keeps the list for you. [PromptInput](page:chat/prompt-input#files) covers that.

## Asking first

Some calls shouldn't run until a person says so: the ones that send, pay, or delete. Set `status="approval"` and put a `ToolCallApproval` in the card with the question. It's drawn only while the call waits, and outside the part that opens, so it's seen with the card closed.

```tsx
"use client";

import {
  ToolCall,
  ToolCallApproval,
  ToolCallContent,
  ToolCallInput,
  ToolCallOutput,
  type ToolCallStatus,
  ToolCallTrigger,
} from "@nuvui/chat";
import { Button } from "@nuvui/react";
import { useEffect, useRef, useState } from "react";

export default function Example() {
  const [status, setStatus] = useState<ToolCallStatus>("approval");
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);

  // Stands in for the tool doing its work.
  function approve() {
    setStatus("running");
    timer.current = setTimeout(() => setStatus("done"), 1500);
  }

  return (
    <div
      style={{
        display: "grid",
        gap: "0.75rem",
        justifyItems: "start",
        inlineSize: "100%",
        maxInlineSize: 520,
      }}
    >
      <ToolCall status={status}>
        <ToolCallTrigger>Send a reminder</ToolCallTrigger>
        <ToolCallContent>
          <ToolCallInput
            value={{ invoice: "INV-1042", to: "billing@contoso.example" }}
          />
          {status === "done" ? <ToolCallOutput value="Sent at 10:42." /> : null}
        </ToolCallContent>
        <ToolCallApproval
          onApprove={approve}
          onDeny={() => setStatus("denied")}
        >
          Send a reminder for INV-1042 to Contoso?
        </ToolCallApproval>
      </ToolCall>
      <Button
        intent="secondary"
        size="sm"
        onClick={() => {
          clearTimeout(timer.current);
          setStatus("approval");
        }}
      >
        Ask again
      </Button>
    </div>
  );
}
```

What happens next is yours. `onApprove` and `onDeny` tell you which button was pressed, and you move `status` on: to `"running"` and then `"done"`, or to `"denied"`.

When a button is pressed, both go. Focus moves to the card's top line first, so it isn't left on nothing.

## While the assistant works

Set `streaming` for as long as it's thinking. The steps open, the line shimmers, and the step with `status="active"` shows a spinner. When `streaming` goes back to `false` they close.

```tsx
"use client";

import {
  Message,
  MessageContent,
  MessageLoader,
  Reasoning,
  ReasoningContent,
  ReasoningStep,
  ReasoningSteps,
  ReasoningTrigger,
} from "@nuvui/chat";
import { Button } from "@nuvui/react";
import { useEffect, useState } from "react";

const steps = [
  "Looked up Contoso's open invoices",
  "Checked the payment terms",
  "Worked out how late each one is",
];

export default function Example() {
  // How many steps have been taken. One more than there are, and the
  // reply is written.
  const [taken, setTaken] = useState(steps.length + 1);
  const thinking = taken <= steps.length;

  // Stands in for the assistant: a step every 900 milliseconds.
  useEffect(() => {
    if (!thinking) return;
    const timer = setInterval(() => setTaken((now) => now + 1), 900);
    return () => clearInterval(timer);
  }, [thinking]);

  return (
    <div
      style={{
        display: "grid",
        gap: "0.75rem",
        justifyItems: "start",
        inlineSize: "100%",
        maxInlineSize: 520,
      }}
    >
      <Message from="assistant" streaming={thinking}>
        <Reasoning streaming={thinking}>
          <ReasoningTrigger>
            {thinking ? "Thinking" : "Thought for 3 seconds"}
          </ReasoningTrigger>
          <ReasoningContent>
            <ReasoningSteps>
              {steps.slice(0, taken + 1).map((step, index) => (
                <ReasoningStep
                  key={step}
                  label={step}
                  status={index === taken ? "active" : "done"}
                />
              ))}
            </ReasoningSteps>
          </ReasoningContent>
        </Reasoning>
        {thinking ? (
          <MessageLoader />
        ) : (
          <MessageContent>
            Two invoices are overdue: INV-1042 by 12 days and INV-1057 by 3.
          </MessageContent>
        )}
      </Message>
      <Button
        intent="secondary"
        size="sm"
        disabled={thinking}
        onClick={() => setTaken(0)}
      >
        Ask again
      </Button>
    </div>
  );
}
```

If the reader opens or closes the steps themselves, that's kept: from then on `streaming` doesn't move them. Someone who closed them isn't shown them again, and someone who opened them to read isn't interrupted.

