              label={names[column.id] ?? column.id}
            >
              <KanbanColumnHeader count={column.cards.length}>
                {names[column.id]}
              </KanbanColumnHeader>
              <KanbanCards empty="No tickets">
                {column.cards.map((id) => (
                  <KanbanCard
                    key={id}
                    value={id}
                    label={`${id}, ${tickets[id]?.title}`}
                  >
                    <div style={{ display: "grid", gap: "0.5rem" }}>
                      <div
                        style={{
                          display: "flex",
                          gap: "0.5rem",
                          alignItems: "center",
                        }}
                      >
                        <span
                          style={{ color: "var(--color-muted-foreground)" }}
                        >
                          {id}
                        </span>
                        {tickets[id]?.urgent ? (
                          <Badge intent="danger">Urgent</Badge>
                        ) : null}
                      </div>
                      <div>{tickets[id]?.title}</div>
                      <div>
                        <Button
                          intent="secondary"
                          size="sm"
                          aria-label={`Open ${id}`}
                          onClick={() => setOpened(`Opened ${id}.`)}
                        >
                          Open
                        </Button>
                      </div>
                    </div>
                  </KanbanCard>
                ))}
              </KanbanCards>
            </KanbanColumn>
          ))
        }
      </Kanban>
      <p role="status" style={{ margin: 0 }}>
        {opened}
      </p>
    </div>
  );
}
```

## It's large, so load it when it's needed

The editor is about 120 kB compressed, nearly all of it ProseMirror. Most screens of an app don't have one. Load it with the screen that does:

```tsx
import { lazy, Suspense } from "react";

const RichTextEditor = lazy(() =>
  import("@nuvui/editor").then((module) => ({
    default: module.RichTextEditor,
  })),
);

<Suspense fallback={<Skeleton style={{ blockSize: "12rem" }} />}>
  <RichTextEditor aria-label="Notes" />
</Suspense>;
```

In Next.js, `next/dynamic` does the same.

## The value

`value` is HTML, and `onValueChange` is called with the HTML each time the text changes. `defaultValue` lets the editor keep it. Nothing written is `""`, not an empty paragraph.

The second argument of `onValueChange` has what else you may want from the same change: `text`, the words with no markup, `characters`, `words`, `empty`, and `json`, the document as data. `json` and `text` are worked out when you read them, so one you don't read costs nothing.

```tsx
"use client";

import { RichTextEditor } from "@nuvui/editor";
import { Button } from "@nuvui/react";
import { useState } from "react";

const start =
  "<p>Payment is due <strong>30 days</strong> after the invoice.</p>";

export default function Example() {
  const [html, setHtml] = useState(start);
  const [counts, setCounts] = useState("8 words");

  return (
    <div
      style={{
        display: "grid",
        gap: "0.75rem",
        inlineSize: "100%",
        maxInlineSize: 640,
      }}
    >
      <RichTextEditor
        aria-label="Payment terms"
        value={html}
        onValueChange={(next, change) => {
          setHtml(next);
          setCounts(`${change.words} words`);
        }}
      />
      <div style={{ display: "flex", gap: "0.75rem", alignItems: "center" }}>
        <Button
          intent="secondary"
          onClick={() => {
            setHtml(start);
            setCounts("8 words");
          }}
        >
          Put it back
        </Button>
        <span role="status">{counts}</span>
      </div>
      <pre
        data-html=""
        style={{
          margin: 0,
          padding: "0.75rem",
          overflowX: "auto",
          borderRadius: "var(--radius-md)",
          backgroundColor: "var(--color-muted)",
          fontSize: "var(--text-xs)",
          whiteSpace: "pre-wrap",
        }}
      >
        {html || "(nothing written)"}
      </pre>
    </div>
  );
}
```

When you set `value` to something other than what's written, the text is replaced and the caret goes to the start. Setting it to what `onValueChange` just gave you changes nothing, so typing isn't disturbed.

## A limit

`maxLength` is the most characters the text takes. Typing and pasting stop there, and a count under the text says how many are written and how many can be. The count turns to the danger color when it's full, and says so in words as well: "140 of 140 characters".

```tsx
"use client";

import { RichTextEditor } from "@nuvui/editor";

export default function Example() {
  return (
    <div style={{ inlineSize: "100%", maxInlineSize: 640 }}>
      <RichTextEditor
        aria-label="Summary"
        maxLength={140}
        placeholder="A summary in 140 characters"
        defaultValue="<p>Two invoices are overdue.</p>"
      />
    </div>
  );
}
```

It counts characters of text, not of HTML. If a column in your database limits the HTML, check that on the server.

## In a form

With a `name`, the HTML is sent with the form the editor is in, in a hidden field, as any other field's value is. A `disabled` editor sends nothing.

Name the editor with `aria-labelledby` and the `id` of the words that label it. A `label` element can't point at it with `for`, since it isn't an `input`. `aria-describedby`, `aria-invalid` and `aria-required` on `RichTextEditor` go to the text, where a screen reader looks for them.

```tsx
"use client";

import { RichTextEditor } from "@nuvui/editor";
import { Button } from "@nuvui/react";
import { type FormEvent, useId, useState } from "react";

export default function Example() {
  const id = useId();
  const [sent, setSent] = useState("Nothing sent yet.");
  const [missing, setMissing] = useState(false);

  function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const body = String(new FormData(event.currentTarget).get("body") ?? "");
    setMissing(body === "");
    if (body !== "") setSent(`Sent: ${body}`);
  }

  return (
    <form
      onSubmit={submit}
      style={{
        display: "grid",
        gap: "0.75rem",
        inlineSize: "100%",
        maxInlineSize: 640,
      }}
    >
      <span id={`${id}-label`} style={{ fontWeight: 500 }}>
        Reply
      </span>
      <RichTextEditor
        name="body"
        aria-labelledby={`${id}-label`}
        aria-describedby={missing ? `${id}-error` : undefined}
        aria-invalid={missing || undefined}
        aria-required
        onValueChange={() => setMissing(false)}
      />
      {missing ? (
        <p
          id={`${id}-error`}
          style={{ margin: 0, color: "var(--color-danger)" }}
        >
          Write a reply before you send it.
        </p>
      ) : null}
      <div>
        <Button type="submit">Send</Button>
      </div>
      <p role="status" style={{ margin: 0, overflowWrap: "anywhere" }}>
        {sent}
      </p>
    </form>
  );
}
```

`aria-required` says it's required. It doesn't stop the form: check for `""` yourself, as above.

## A menu on the selection

`RichTextEditorBubbleMenu` is a small toolbar that comes up over text when it's selected, with bold, italic, underline and strikethrough, or the `items` you give it. It's for an editor with no toolbar over the text, as here.

```tsx
"use client";

import {
  RichTextEditor,
  RichTextEditorBubbleMenu,
  RichTextEditorContent,
} from "@nuvui/editor";

export default function Example() {
  return (
    <div style={{ inlineSize: "100%", maxInlineSize: 640 }}>
      <RichTextEditor
        aria-label="Release note"
        defaultValue="<p>Select a few of these words to format them.</p>"
      >
        <RichTextEditorContent />
        <RichTextEditorBubbleMenu />
      </RichTextEditor>
    </div>
  );
}
```

It isn't drawn unless you add it. Under a toolbar it covers the toolbar's controls when the first line is selected, and on a phone it comes up where the phone's own menu for copy and paste does. Formatting that's only in this menu can't be reached with the Tab key, so keep it to formats that have a shortcut: the four it starts with do.

## Read only

`readOnly` shows the text and lets it be selected and copied, and not changed. With only `RichTextEditorContent` as its child there's no toolbar, and it's a way to show saved text: the editor reads HTML through the same rules it writes with, so what it shows can't run anything.

```tsx
"use client";

import { RichTextEditor, RichTextEditorContent } from "@nuvui/editor";

// What someone wrote, shown again. The editor reads the HTML through its
// own rules for what text can hold, so nothing in it can run.
const saved =
  '<h3>Late payments</h3><p>A reminder goes out on <strong>day 31</strong>.</p><ul><li><p>Late fees start at day 45.</p></li><li><p>Questions go to <a href="mailto:billing@example.com">billing@example.com</a>.</p></li></ul>';

export default function Example() {
  return (
    <div style={{ inlineSize: "100%", maxInlineSize: 640 }}>
      <RichTextEditor
        aria-label="Payment terms, as saved"
        readOnly
        headingLevels={[3]}
        value={saved}
        style={{ "--nuv-rich-text-editor-min-height": "0" } as never}
      >
        <RichTextEditorContent />
      </RichTextEditor>
    </div>
  );
}
```

`disabled` is for a field that can't be used now. It's dimmed, and isn't sent with a form.

## In a popover

The picker is a panel, and has no button of its own. Most often it opens from one, in a [popover](page:components/popover). `autoFocus` puts the caret in the search box when it opens, so a name can be typed at once and Enter picks the first emoji found.

```tsx
"use client";

import { EmojiPicker } from "@nuvui/emoji";
import { Button, Popover, PopoverContent, PopoverTrigger } from "@nuvui/react";
import { type CSSProperties, useState } from "react";

// The popover is the panel's edge here, so it gives up its own width and
// padding, and the picker gives up its border.
const bare = {
  "--nuv-popover-width": "auto",
  "--nuv-popover-padding": "0px",
  "--nuv-emoji-picker-border": "transparent",
} as CSSProperties;

export default function Example() {
  const [open, setOpen] = useState(false);
  const [text, setText] = useState("Shipped");

  return (
    <div style={{ display: "grid", gap: 12, justifyItems: "start" }}>
      <p style={{ margin: 0 }} data-text>
        {text}
      </p>
      <Popover open={open} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <Button intent="secondary">Add an emoji</Button>
        </PopoverTrigger>
        <PopoverContent aria-label="Pick an emoji" align="start" style={bare}>
          <EmojiPicker
            autoFocus
            onEmojiSelect={(emoji) => {
              setText((now) => `${now} ${emoji}`);
              setOpen(false);
            }}
          />
        </PopoverContent>
      </Popover>
    </div>
  );
}
```

The popover gives up its width and its padding here, and the picker its border, so the two are one panel. Where there's less room than the picker's height, the picker is made shorter to fit, and its list stays the one thing that scrolls.

## What's picked

`onEmojiSelect` is called with the emoji as text, in the skin tone that's set, and with what the list knows of it: its name, its group, and the emoji with no tone.

```tsx
<EmojiPicker
  onEmojiSelect={(emoji, item) => {
    insert(emoji); // "👋🏽"
    log(item.label); // "waving hand"
  }}
/>
```

## The ones picked before

The last sixteen emoji picked are listed first the next time the picker is drawn. They aren't added while it's open, so nothing moves under the pointer as emoji are picked.

They're kept in the browser's local storage, with the skin tone, under the name `storageKey` gives, which is `"nuvui-emoji"`. To keep them with someone's account, so they follow from one device to the next, give `recent` and `onRecentChange`, and `storageKey={null}` to keep nothing in the browser.

```tsx
"use client";

import { EmojiPicker, type EmojiSkinTone } from "@nuvui/emoji";
import { useState } from "react";

export default function Example() {
  // Kept here, where an app would keep them with the account, so they
  // follow someone from one device to the next.
  const [recent, setRecent] = useState(["👍", "🎉", "🚀"]);
  const [tone, setTone] = useState<EmojiSkinTone>(3);

  return (
    <div style={{ display: "grid", gap: 12, justifyItems: "center" }}>
      <EmojiPicker
        storageKey={null}
        recent={recent}
        onRecentChange={setRecent}
        skinTone={tone}
        onSkinToneChange={setTone}
      />
      <p style={{ margin: 0, fontSize: "var(--text-sm)" }} data-kept>
        Recent: {recent.join(" ")}. Skin tone: {tone}.
      </p>
    </div>
  );
}
```

Kept by you, the list is drawn as you give it. Give it the new list when the picker is next opened, and not while it's open, if emoji shouldn't move.

## A list of your own

`data` takes the emoji to list: other names, another language, or only the ones that fit. Each is an emoji, a name, the group it's in, and optionally other words to find it by, its version, and its five skin tones.

```tsx
"use client";

import { type EmojiItem, EmojiPicker } from "@nuvui/emoji";
import type { CSSProperties } from "react";
import { useState } from "react";

// The few a comment can be answered with, named in Dutch.
