// Made-up files for a made-up team. Nothing here is real data.

interface Entry {
  id: string;
  name: string;
  // A folder has entries, even if none. A file has a size.
  entries?: Entry[];
  size?: string;
  changed?: string;
  by?: string;
}

const start: Entry[] = [
