        size: "1.2 MB",
        changed: "October 6",
        by: "Bo Jensen",
      },
      {
        id: "reports/q3-summary.pdf",
        name: "q3-summary.pdf",
        size: "96 KB",
        changed: "October 7",
        by: "Ada Lovelace",
      },
    ],
  },
  { id: "archive", name: "Archive", entries: [] },
