    var(--color-foreground)
  );
  background-repeat: no-repeat;
  background-position: 14% 62%;
  background-size: 48% 16%;
}

.before-after__chart {
  display: flex;
  grid-column: 1 / -1;
  gap: 5%;
  align-items: end;
  padding: 5% 6%;
  border: var(--nuv-border-width) solid var(--color-border);
  border-radius: var(--radius-md);
